import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import './Research.css';
// Re-use Navbar styles

const ResearchPage = () => {
  // --- UI STATES ---
  const [activeTab, setActiveTab] = useState('overview'); // Tabs: overview, areas, pubs, downloads
  
  // --- NAV STATES ---
  const [activeCategory, setActiveCategory] = useState('Air Quality');
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
  const [isSolutionsMenuOpen, setIsSolutionsMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  

  // --- DATA ---
  const [brochures, setBrochures] = useState([]);
  const API_BASE_URL = 'https://aiiot-1.onrender.com';

  // --- FETCH BROCHURES (Existing Logic) ---
  useEffect(() => {
    const fetchBrochures = async () => {
      try {
        const response = await axios.get(`${API_BASE_URL}/api/brochures/`);
        // Filter out only active brochures
        setBrochures(response.data.filter(b => b.is_active));
      } catch (error) {
        console.error('Error fetching brochures:', error);
      }
    };
    fetchBrochures();
  }, []);

  // --- NAV DATA ---
  const solutionsList = [
    { name: 'Air Quality Monitoring', link: '/project/intelligent-sensor' },
    { name: 'Flood Alert System', link: '/project/water-level' },
    { name: 'Digital Water Distribution', link: '/project/digital-water' },
    { name: 'Startup & Skill Development', link: '/project/startup-skill' }
  ];

  const productMenuData = {
    'Air Quality': {
      title: 'Air Quality Monitoring',
      description: 'Precision sensors for indoor and outdoor environments.',
      items: [
        { name: 'Indoor Air Quality Monitor', image: '/sensor_modules/aqicrop.jpeg', link: '/product-details/indoor-monitor' },
        { name: 'AQM v3 (Outdoor Station)', image: '/sensor_modules/aqi1.jpeg', link: '/product-details/outdoor-station' },
        { name: 'Gas Sensors', image: 'https://images.unsplash.com/photo-1621905252507-b35492cc74b4?w=400', link: '/product-details/gas-sensors' }
      ]
    },
    'Water Solutions': {
      title: 'Water Management',
      description: 'Flood alerts and distribution logic.',
      items: [
        { name: 'Smart Flood Alert System', image: '/sensor_modules/river1.jpg', link: '/product-details/flood-alert' },
        { name: 'Digital Flow Meter', image: '/sensor_modules/distribution.jpeg', link: '/product-details/distribution-net' }
      ]
    },
    'Weather': {
      title: 'Weather Stations',
      description: 'Hyper-local weather data collection.',
      items: [
        { name: 'AWS v1 & v2', image: '/sensor_modules/weather.jpg', link: '/product-details/weather-station' },
        { name: 'Rain Gauges', image: 'https://images.unsplash.com/photo-1590055531860-6902633df018?w=400', link: '/product-details/rain-gauge' }
      ]
    },
    'Training': {
      title: 'Skill Development',
      description: 'Kits and workshops for students.',
      items: [
        { name: 'IoT Workshops & Internships', image: '/sensor_modules/skill.jpg', link: '/product-details/iot-training' },
        { name: 'PCB Design Course', image: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=400', link: '/product-details/pcb-workshop' }
      ]
    }
  };

  return (
    <div className="research-page">
      
      {/* 1. HEADER (Standardized) */}
      <header className="aiiot-header-local">
         <div className="project-header-inner">
             <Link to="/" className="logo-link">
               <div className="logo-box">
                 <img src="/logo/logo.png" alt="Adi Shankara" style={{ height: '100%', width: 'auto' }} />
               </div>
               <div style={{ display: 'flex', flexDirection: 'column' }}>
                 <span style={{ fontSize: '1.1rem', fontWeight: 700, color: '#1e293b' }}>AI-IoT Innovations</span>
               </div>
             </Link>
 
             {/* DESKTOP NAV */}
             <div className="project-desktop-nav">
               <Link to="/" className="project-nav-link">Home</Link>
               
               {/* Solutions Dropdown */}
               <div className="dropdown-wrapper" onMouseEnter={() => setIsSolutionsMenuOpen(true)} onMouseLeave={() => setIsSolutionsMenuOpen(false)}>
                   <div className="project-nav-link product-trigger" style={{ cursor: 'pointer' }}>Solutions <span>▾</span></div>
                   <div className={`simple-dropdown ${isSolutionsMenuOpen ? 'visible' : ''}`}>
                     {solutionsList.map((sol, index) => (
                       <Link key={index} to={sol.link} className="simple-dropdown-item">{sol.name}</Link>
                     ))}
                   </div>
               </div>

               {/* Products Mega Menu */}
               <div className="mega-menu-wrapper" onMouseEnter={() => setIsMegaMenuOpen(true)} onMouseLeave={() => setIsMegaMenuOpen(false)}>
                 <Link to="/products" className="project-nav-link product-trigger">Products <span>▾</span></Link>
                 <div className={`mega-menu-container ${isMegaMenuOpen ? 'visible' : ''}`}>
                   <div className="mega-menu-sidebar">
                     {Object.keys(productMenuData).map((key) => (
                       <div key={key} className={`mega-sidebar-item ${activeCategory === key ? 'active' : ''}`} onMouseEnter={() => setActiveCategory(key)}>
                         {key} <span>›</span>
                       </div>
                     ))}
                   </div>
                   <div className="mega-menu-content">
                     <div className="mega-content-header">
                       <h4>{productMenuData[activeCategory].title}</h4>
                       <p>{productMenuData[activeCategory].description}</p>
                     </div>
                     <div className="mega-grid">
                       {productMenuData[activeCategory].items.map((item, idx) => (
                         <Link to={item.link} key={idx} className="mega-product-card">
                            <div className="mega-img-box"><img src={item.image} alt={item.name} /></div>
                            <span>{item.name}</span>
                         </Link>
                       ))}
                     </div>
                   </div>
                 </div>
               </div>
               
               <Link to="/research" className="project-nav-link" style={{color:'#3b82f6'}}>R&D</Link>
               <a href="#contact" className="btn-primary-small">Get in Touch</a>
             </div>
 
             <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
               {isMobileMenuOpen ? '✕' : '☰'}
             </button>
         </div>

         {/* MOBILE MENU (Condensed for brevity - same as other files) */}
         {isMobileMenuOpen && (
            <div className="mobile-menu-wrapper">
                <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">Home</Link>
                <Link to="/research" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">R&D Center</Link>
                <a href="#contact" className="btn-primary" style={{ textAlign: 'center', marginTop: '1rem' }}>Contact</a>
            </div>
         )}
      </header>

      {/* 2. HERO SECTION */}
      <div className="research-hero">
        <h1 className="research-title">Research & Development</h1>
        <p className="research-subtitle">
          Pioneering the future of Environmental Intelligence. We bridge the gap between academic research and industrial application through AI, IoT, and Edge Computing.
        </p>
      </div>

      {/* 3. TABS NAVIGATION */}
      <div className="research-tabs">
        <button className={`tab-btn ${activeTab === 'overview' ? 'active' : ''}`} onClick={() => setActiveTab('overview')}>Overview</button>
        <button className={`tab-btn ${activeTab === 'areas' ? 'active' : ''}`} onClick={() => setActiveTab('areas')}>Focus Areas</button>
        <button className={`tab-btn ${activeTab === 'pubs' ? 'active' : ''}`} onClick={() => setActiveTab('pubs')}>Publications & Patents</button>
        <button className={`tab-btn ${activeTab === 'downloads' ? 'active' : ''}`} onClick={() => setActiveTab('downloads')}>Brochures & Resources</button>
      </div>

      <div className="research-container">
        
        {/* --- TAB: OVERVIEW --- */}
        {activeTab === 'overview' && (
          <div className="areas-grid">
             <div className="area-card" style={{borderLeft:'5px solid #10b981'}}>
                <h3 style={{fontSize:'1.5rem', marginBottom:'1rem'}}>🚀 Our Mission</h3>
                <p style={{lineHeight:'1.6', color:'#475569'}}>
                  To develop digital networking solutions for preventive and predictive environmental warning. We focus on integrating electronics hardware design with Artificial Intelligence (AI) and Explainable AI (XAI).
                </p>
             </div>
             <div className="area-card" style={{borderLeft:'5px solid #3b82f6'}}>
                <h3 style={{fontSize:'1.5rem', marginBottom:'1rem'}}>🎯 Key Objectives</h3>
                <ul style={{listStyle:'none', padding:0, color:'#475569', lineHeight:'1.8'}}>
                   <li>✓ Develop intelligent sensors for pollution monitoring.</li>
                   <li>✓ Validate smart water level monitoring systems.</li>
                   <li>✓ Create digital twins for water distribution.</li>
                   <li>✓ Build a vibrant startup & skill ecosystem.</li>
                </ul>
             </div>
          </div>
        )}

        {/* --- TAB: FOCUS AREAS --- */}
        {activeTab === 'areas' && (
          <div className="areas-grid">
            <div className="area-card">
              <span className="area-icon">🧠</span>
              <h3>Explainable AI (XAI)</h3>
              <p>Developing AI models that are not black boxes. We focus on interpretable machine learning for environmental forecasting.</p>
            </div>
            <div className="area-card">
              <span className="area-icon">📡</span>
              <h3>IoT & Edge Computing</h3>
              <p>Designing low-power, long-range (LoRaWAN) sensor nodes capable of processing data at the edge.</p>
            </div>
            <div className="area-card">
              <span className="area-icon">🌊</span>
              <h3>Hydro-Informatics</h3>
              <p>Using LSTM networks to predict river levels and flood risks 6 hours in advance for the Periyar river basin.</p>
            </div>
            <div className="area-card">
              <span className="area-icon">🏭</span>
              <h3>Industrial Safety</h3>
              <p>Detecting hazardous gas leaks (Ammonia, Chlorine) in real-time using high-precision electrochemical sensors.</p>
            </div>
          </div>
        )}

        {/* --- TAB: PUBLICATIONS --- */}
        {activeTab === 'pubs' && (
          <div>
            <h2 style={{fontSize:'2rem', marginBottom:'2rem'}}>Research Output</h2>
            
            <div style={{marginBottom:'3rem'}}>
              <h3 style={{color:'#3b82f6', marginBottom:'1rem'}}>📜 Patents Filed</h3>
              <div className="pub-item" style={{borderLeftColor:'#f59e0b'}}>
                <div className="pub-title">Intelligent Water Level Monitoring & Alert System</div>
                <div className="pub-meta">Status: Filed / Pending Examination (Application No: 2024410XXXX)</div>
              </div>
            </div>

            <div>
              <h3 style={{color:'#3b82f6', marginBottom:'1rem'}}>📚 Selected Publications</h3>
              <div className="pub-item">
                <div className="pub-title">Forecasting River Water Levels Using LSTM Neural Networks</div>
                <div className="pub-meta">IEEE Access, 2024 • Authors: Dr. Ajay Kumar, et al.</div>
              </div>
              <div className="pub-item">
                <div className="pub-title">Design of Low-Power LoRaWAN Nodes for Air Quality Monitoring</div>
                <div className="pub-meta">International Conference on Smart Systems (ICSS), 2023</div>
              </div>
              <div className="pub-item">
                <div className="pub-title">Explainable AI in Environmental Sensing: A Case Study</div>
                <div className="pub-meta">Journal of Environmental Informatics, 2024</div>
              </div>
            </div>
          </div>
        )}

        {/* --- TAB: DOWNLOADS (Old Resources Page Content) --- */}
        {activeTab === 'downloads' && (
          <div>
            <h2 style={{fontSize:'2rem', marginBottom:'2rem'}}>Downloads & Assets</h2>
            {brochures.length === 0 ? (
                <p>Loading brochures...</p>
            ) : (
                <div className="areas-grid">
                    {brochures.map((b, idx) => (
                        <div key={idx} className="download-card">
                            <div>
                                <h4 style={{fontWeight:'700', marginBottom:'0.5rem'}}>{b.title}</h4>
                                <p style={{fontSize:'0.9rem', color:'#64748b'}}>{b.category}</p>
                            </div>
                            <a href={b.file.startsWith('http') ? b.file : `${API_BASE_URL}${b.file}`} target="_blank" rel="noopener noreferrer" className="download-btn-small">
                                Download PDF
                            </a>
                        </div>
                    ))}
                </div>
            )}
          </div>
        )}

      </div>
    </div>
  );
};

export default ResearchPage;
